     *
     * // Get movies releasing in the next 7 days
     * let movies = calendar.get_my_movies("2024-01-15".to_string(), 7).await?;
     * for movie in movies {
     * println!("{} ({})", movie.movie.title, movie.released);
     * }
     * # Ok(())
     * # }
     * ```
     */
